    vsWord: "vs",
    seeMyProgress: "See my progress",
    howRankingWorks: "How is this counted?",
    rankHelpHtml: "<p><b>A match</b> — first to 21; after 20-all the winner must lead by 2; {cap} is the most (the official badminton rule, BWF Laws of Badminton, stops at 30).</p><p><b>Rating (Elo)</b> — everyone starts at <b>{start}</b>. When you win, you take points from the losers; how many depends on how strong they were: beating a higher-rated team gives more, beating a weaker one gives less (K = {k}). A bigger point difference adds a little more. Doubles uses the average of the two players. It is the same idea as the Elo rating used in chess (FIDE) and the World Football Elo Ratings.</p><p><b>Every saved match</b> with a score changes ratings. Fun, Exercise and Competition are only a label that tells the players how the match was meant; they all count.</p><p><b>Ranking</b> — players and pairs are ordered by rating. Until you have {min} matches (a pair: {pmin}), your rating is still settling: it is tagged x/{min} matches; players who are still settling are listed after the others, pairs stay in rating order. <b>Best pair</b> is the pair with the highest rating; <b>Best score</b> is the match with the biggest winning margin.</p><p><b>Why not BWF World Tour points?</b> The BWF World Ranking gives points for how far you get in a tournament (e.g. Super 1000 winner 12,000 points) and keeps your best 10 results of the last 52 weeks. That needs tournaments and draws; for weekly club matches, Elo is fairer because every single match counts and wins against strong players count more.</p><p><b>Levels</b> (BG … B&A) are set by people, not by the rating.</p>",
