    tip_rival_2: "ກັບ {name} ຕີໄປມຸມຫຼັງກ່ອນ ແລ້ວຕີລູກສັ້ນເພື່ອເປີດຊ່ອງວ່າງ.",
    tip_rival_3: "{name} ເຮັດໃຫ້ທ່ານຕ້ອງອອກແຮງ. ຕີໃຫ້ປອດໄພ ແລະ ລໍຖ້າໃຫ້ເຂົາພາດກ່ອນ.",
    tip_rival_4: "ຈົດບັນທຶກຫຼັງແມັດກັບ {name}: ອັນໃດໄດ້ຜົນ? ເຮັດຊ້ຳສະເພາະອັນນັ້ນ.",
    tip_easy_1: "ທ່ານສະບາຍຕອນແຂ່ງກັບ {name}. ຂໍແມັດທີ່ຍາກຂຶ້ນ: ຫຼິ້ນຮອດ 25 ຫຼື ສະຫຼັບຄູ່.",
    tip_easy_2: "ທ່ານຊະນະ {name} ເລື້ອຍໆ. ໃຊ້ແມັດເຫຼົ່ານັ້ນລອງລູກຕີໃໝ່ທີ່ຍັງບໍ່ໝັ້ນໃຈ.",
    tip_easy_3: "ກັບ {name} ທ່ານນຳຢູ່. ແບ່ງປັນເຄັດລັບໃຫ້ເຂົາ, ການສອນຊ່ວຍໃຫ້ການຫຼິ້ນຂອງທ່ານແໜ້ນຂຶ້ນ.",
    tip_close_1: "ຫຼາຍແມັດຂອງທ່ານສູ້ກັນໃກ້ຊິດ. ຝຶກຕອນທ້າຍແມັດ (18–20): ໃຈເຢັນ, ເສີບໃຫ້ປອດໄພ, ຮັກສາລູກໃຫ້ຕ່ຳ.",
    tip_close_2: "ແມັດໃກ້ຊິດຕັດສິນຫຼາຍຢ່າງ. ຕອນ 18 ເທົ່າ ຫາຍໃຈເຂົ້າເລິກໆ, ຊ້າລົງລະຫວ່າງຄະແນນ, ແລະ ຕີລູກທີ່ປອດໄພທີ່ສຸດ.",
    tip_close_3: "ແມັດຂອງທ່ານສູ້ກັນໃກ້ຊິດ; ເພີ່ມອີກໜຶ່ງຄະແນນຕໍ່ແມັດກໍປ່ຽນຜົນ. ຝຶກເສີບ ແລະ ຮັບເສີບໃຫ້ສະໝ່ຳສະເໝີ.",
    tip_blowout_1: "ບາງແມັດຫຼຸດໄວຕັ້ງແຕ່ຕົ້ນ. ເລີ່ມໃຫ້ໄວ: ວອມອັບໃຫ້ດີ ແລະ ພ້ອມຕັ້ງແຕ່ເສັ້ນທຳອິດ.",
    tip_blowout_2: "ເວລາເປັນຝ່າຍຕາມ ຢ່າຮີບ. ເລືອກລູກທີ່ປອດໄພອັນໜຶ່ງ ແລ້ວສ້າງເສັ້ນໃໝ່.",
    tip_blowout_3: "ຄະແນນຫ່າງມັກເລີ່ມຈາກຜິດພາດຕິດກັນ. ພັກສັ້ນໆໃນໃຈ ແລ້ວຣີເຊັດ.",
    tip_rest_1: "ແພ້ຕິດກັນສັ້ນໆເກີດກັບທຸກຄົນ. ພັກ, ດື່ມນ້ຳ, ວອມອັບໃຫ້ດີ; ແມັດຕໍ່ໄປເລີ່ມໃໝ່.",
    tip_rest_2: "ແພ້ສອງແມັດຕິດ: ພັກດົນຂຶ້ນ, ຍືດເສັ້ນ, ແລະ ປ່ຽນສິ່ງນ້ອຍໆອັນໜຶ່ງໃນແມັດຕໍ່ໄປ.",
    tip_rest_3: "ຢ່າໄລ່ຕາມແມັດທີ່ແພ້. ນັ່ງພັກໜຶ່ງແມັດ ແລ້ວກັບມາຢ່າງສະບາຍ.",
    tip_streak_1: "ທ່ານກຳລັງຊະນະຕິດ. ຮັກສາທຳນຽມເດີມ: ວອມອັບແບບເດີມ, ພັກດື່ມນ້ຳແບບເດີມ.",
    tip_streak_2: "ຊະນະຕິດ! ຖ່ອມຕົວ, ຮັກສາຝີມືຂາໃຫ້ເບົາ, ແລະ ລົມກັບຄູ່ຕໍ່ໄປ.",
    tip_streak_3: "ຟອມດີ. ລອງລູກໃໝ່ອັນໜຶ່ງຕອນນີ້ ໃນຂະນະທີ່ມີຄວາມໝັ້ນໃຈ.",
    tip_great_1: "ຟອມດີຫຼາຍ! ຮັກສາແບບເດີມ ແລະ ລອງຫຼິ້ນກັບຄູ່ໃໝ່ເປັນບາງເທື່ອເພື່ອຮຽນຮູ້ຕື່ມ.",
    tip_great_2: "ທ່ານຊະນະສ່ວນໃຫຍ່. ທ້າທາຍຕົນເອງ: ບາງເທື່ອຫຼິ້ນກັບຝ່າຍທີ່ອ່ອນກວ່າເພື່ອພັດທະນາທັກສະ.",
    tip_great_3: "ຜົນງານດີເລີດ. ຮັກສາຮ່າງກາຍ ແລະ ພັກຜ່ອນໃຫ້ພໍ ຟອມຈະຢູ່ໄດ້ດົນ.",
    tip_few_1: "ຫຼິ້ນອີກຈັກແມັດ ຄຳແນະນຳຢູ່ນີ້ຈະແມ່ນຍຳຂຶ້ນ.",
    tip_few_2: "ມີບໍ່ຫຼາຍແມັດເທື່ອ. ລອງຫຼິ້ນກັບຄູ່ຕ່າງໆເພື່ອເບິ່ງວ່າແບບໃດໄດ້ຜົນ.",
    tip_mix_1: "ລອງຫຼິ້ນກັບຄູ່ຫຼາຍຄົນ ເພື່ອຊອກຫາຄົນທີ່ເຂົ້າກັບສະໄຕຂອງທ່ານ.",
    tip_mix_2: "ຍັງມີແມັດກັບຄູ່ດຽວກັນບໍ່ພໍ. ສະຫຼັບຄູ່ ແລະ ເບິ່ງວ່າຫຼິ້ນກັບໃຜມ່ວນທີ່ສຸດ.",
    tip_mix_3: "ສະຫຼັບຄູ່ໄປກ່ອນ; ຄູ່ທີ່ດີທີ່ສຸດຈະປາກົດເມື່ອມີແມັດຫຼາຍຂຶ້ນ.",
    tip_gen_1: "ວອມອັບ 5 ນາທີກ່ອນເສັ້ນທຳອິດ: ບ່າ, ຂໍ້ມື ແລະ ຂໍ້ຕີນ.",
    tip_gen_2: "ງໍເຂົ່າ ແລະ ຢືນເທິງປາຍຕີນລະຫວ່າງລູກ; ຝີມືຂາໄດ້ຄະແນນ.",
    tip_gen_3: "ດື່ມນ້ຳທຸກແມັດ ບໍ່ແມ່ນລໍຖ້າຫິວ.",
    tip_gen_4: "ເສີບໃຫ້ປອດໄພກ່ອນ ແລ້ວຄ່ອຍບຸກ. ເສີບໃຫ້ສະໝ່ຳສະເໝີໄດ້ຄະແນນ.",
    tip_gen_5: "ເບິ່ງລູກຈົນຖືກໄມ້ ແລ້ວຄ່ອຍຂະຫຍັບ.",
    tip_gen_6: "ຫຼັງແມັດ ຍືດຂາສອງນາທີ. ຊ່ວຍໃຫ້ແມັດຕໍ່ໄປດີຂຶ້ນ.",
    tip_gen_7: "ລົມກັບຄູ່ຫຼັງທຸກຄະແນນ ເຖິງພຽງຄຳດຽວ.",
    tip_gen_8: "ຫຼິ້ນຕາມຈັງຫວະຂອງຕົນ; ຫາຍໃຈເຂົ້າກ່ອນເສີບທຸກເທື່ອ.",
