    tourSumNext4: "ເກັ່ງສຸດຄູ່ກັບອ່ອນສຸດ. ຈັດຄູ່: 4 ຄົນທຳອິດຫຼິ້ນຮອບຊິງ ດີທີ່ສຸດ 3 ແມັດ.",
    tourSumNext8b: "ເກັ່ງສຸດຄູ່ກັບອ່ອນສຸດ. ຈັດຄູ່: 2 ຮອບຮອງ, ແລ້ວຊິງອັນດັບ 3 ແລະ ຮອບຊິງ, ທັງສອງດີທີ່ສຸດ 3 ແມັດ.",
    tourHowFinal: "4 ຄົນທຳອິດຫຼິ້ນເປັນ 2 ຄູ່: #1 ກັບ #4 ພົບ #2 ກັບ #3. ດີທີ່ສຸດ 3 ແມັດ: ຄູ່ທີ່ໄດ້ 2 ແມັດກ່ອນເປັນແຊ້ມ. ຖ້າຊະນະ 2–0 ຈະປະຢັດ 1 ແມັດ.",
    tourHow8b: "ສີ່ຄູ່ຫຼິ້ນ 2 ຮອບຮອງ: ຄູ່ 1 ພົບຄູ່ 4, ຄູ່ 2 ພົບຄູ່ 3. ຜູ້ແພ້ຫຼິ້ນຊິງອັນດັບ 3, ຜູ້ຊະນະຫຼິ້ນຮອບຊິງ. ທັງສອງດີທີ່ສຸດ 3 ແມັດ: ຄູ່ທີ່ໄດ້ 2 ແມັດກ່ອນຊະນະ.",
