    rankHelpHtml: "<p><b>ໜຶ່ງແມັດ</b> — ໃຜຮອດ 21 ກ່ອນຊະນະ; ຫຼັງ 20-20 ຕ້ອງນຳ 2; ສູງສຸດ {cap} (ກົດທາງການຂອງ BWF ສູງສຸດ 30).</p><p><b>ຄະແນນ (Elo)</b> — ທຸກຄົນເລີ່ມ <b>{start}</b>. ເມື່ອຊະນະ ທ່ານໄດ້ຄະແນນຈາກຝ່າຍແພ້; ໄດ້ຫຼາຍ ຫຼື ໜ້ອຍ ຂຶ້ນກັບຄວາມເກັ່ງຂອງຄູ່ແຂ່ງ: ຊະນະທີມທີ່ຄະແນນສູງກວ່າໄດ້ຫຼາຍ, ຊະນະທີມທີ່ອ່ອນກວ່າໄດ້ໜ້ອຍ (K = {k}). ຊະນະຫ່າງຫຼາຍໄດ້ເພີ່ມອີກໜ້ອຍໜຶ່ງ. ປະເພດຄູ່ໃຊ້ຄ່າສະເລ່ຍຂອງສອງຄົນ. ແນວຄິດດຽວກັບ Elo ຂອງໝາກຮຸກ (FIDE) ແລະ World Football Elo Ratings.</p><p><b>ທຸກແມັດທີ່ບັນທຶກຄະແນນ</b> ປ່ຽນຄະແນນ. ມ່ວນ, ອອກກຳລັງ ແລະ ແຂ່ງຂັນ ເປັນພຽງປ້າຍບອກຜູ້ຫຼິ້ນ; ທຸກແມັດນັບ.</p><p><b>ອັນດັບ</b> — ຄົນ ແລະ ຄູ່ ຮຽງຕາມຄະແນນ. ຖ້າຍັງບໍ່ຮອດ {min} ແມັດ (ຄູ່: {pmin}) ຄະແນນຍັງບໍ່ຄົງທີ່ ແລະ ມີປ້າຍ x/{min} ແມັດ; ຄົນທີ່ຍັງບໍ່ຄົງທີ່ຈະຢູ່ຫຼັງຄົນອື່ນ, ຄູ່ຍັງຮຽງຕາມຄະແນນ. <b>ຄູ່ທີ່ດີທີ່ສຸດ</b> = ຄູ່ທີ່ມີຄະແນນສູງສຸດ; <b>ຄະແນນດີທີ່ສຸດ</b> = ແມັດທີ່ຊະນະຫຼາຍທີ່ສຸດ.</p><p><b>ເປັນຫຍັງບໍ່ໃຊ້ຄະແນນ BWF World Tour?</b> BWF World Ranking ໃຫ້ຄະແນນຕາມຮອບທີ່ໄປຮອດໃນການແຂ່ງ (ເຊັ່ນ ແຊ້ມ Super 1000 ໄດ້ 12,000 ຄະແນນ) ແລະ ນັບ 10 ຜົນງານດີສຸດໃນ 52 ອາທິດ. ຕ້ອງມີການແຂ່ງຂັນ; ສຳລັບແມັດກຸ່ມປະຈຳອາທິດ Elo ຍຸຕິທຳກວ່າ ເພາະທຸກແມັດນັບ ແລະ ຊະນະຄົນເກັ່ງນັບຫຼາຍກວ່າ.</p><p><b>ລະດັບ</b> (BG … B&A) ຄົນເປັນຜູ້ຕັ້ງ, ບໍ່ແມ່ນຈາກຄະແນນ.</p>",
