/**
 * Get a translation by key
 */
function t(key) {
  var lang = translations[currentLang] || translations.en;
  var r = lang[key] || translations.en[key];
  if (r) return r;
  // A missing key is shown as text: keys are often built from stored data (t("mode_" + doc.mode)), so it must never become HTML
  return String(key).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

/**
 * Set the active language
 */
function setLang(lang) {
  currentLang = lang;
  try { localStorage.setItem("lang", lang); } catch (e) {}
  applyI18n();
  if (typeof setAuthMode === "function" && typeof authMode !== "undefined") setAuthMode(authMode);
  if (typeof refreshCurrentPage === "function") refreshCurrentPage("lang");
}

/**
 * Toggle between English and Lao
 */
function toggleLang() {
  setLang(currentLang === "en" ? "la" : "en");
}

/**
 * Apply translations to all DOM elements with data-i18n
 */
function applyI18n() {
  // Elements with data-i18n attribute
  var els = document.querySelectorAll("[data-i18n]");
  for (var i = 0; i < els.length; i++) {
    var key = els[i].getAttribute("data-i18n");
    var tag = els[i].tagName.toLowerCase();

    if (tag === "input" || tag === "textarea") {
      els[i].placeholder = t(key);
    } else {
      els[i].textContent = t(key);
    }
  }

  // Screen-reader labels
  var arEls = document.querySelectorAll("[data-i18n-aria]");
  for (var a = 0; a < arEls.length; a++) arEls[a].setAttribute("aria-label", t(arEls[a].getAttribute("data-i18n-aria")));

  // Elements with data-i18n-placeholder (explicit placeholder override)
  var phEls = document.querySelectorAll("[data-i18n-placeholder]");
  for (var j = 0; j < phEls.length; j++) {
    var pKey = phEls[j].getAttribute("data-i18n-placeholder");
    phEls[j].placeholder = t(pKey);
  }

  // Special elements
  var headerTitle = document.getElementById("headerTitle");
  if (headerTitle) headerTitle.textContent = t("headerTitle");

  var headerSub = document.getElementById("headerSub");
  if (headerSub) headerSub.textContent = t("headerSub");

  // Language buttons: Solar globe + the language you can switch to
  var globe = typeof icon === "function" ? icon("globe", 16) + " " : "";
  var langBtn = document.getElementById("langBtn");
  if (langBtn) langBtn.innerHTML = globe + (currentLang === "en" ? "LA" : "EN");
  var authLangBtn = document.getElementById("authLangBtn");
  if (authLangBtn) authLangBtn.innerHTML = globe + (currentLang === "en" ? "\u0EA5\u0EB2\u0EA7" : "English");
  document.documentElement.lang = currentLang === "la" ? "lo" : "en";
}
